import { parseIsoDate } from './src/parseIsoDate.ts'

let passed = 0
let failed = 0

function assert(label, fn) {
  try {
    fn()
    console.log('  PASS:', label)
    passed++
  } catch (e) {
    console.log('  FAIL:', label)
    console.log('       ', e.message ?? e)
    failed++
  }
}

// AC1: UTC suffix → valid Date with correct ISO string
assert('AC1: Z suffix morphs to Date', () => {
  const d = parseIsoDate('2024-01-15T10:30:00Z')
  if (!(d instanceof Date)) throw new Error('not a Date')
  if (d.toISOString() !== '2024-01-15T10:30:00.000Z') throw new Error('wrong ISO string: ' + d.toISOString())
})

// AC2: numeric offset → Date instance
assert('AC2: +05:00 offset morphs to Date', () => {
  const d = parseIsoDate('2024-01-15T10:30:00+05:00')
  if (!(d instanceof Date)) throw new Error('not a Date')
})

// AC3: no timezone → rejected
assert('AC3: no timezone is rejected', () => {
  try {
    parseIsoDate('2024-01-15T10:30:00')
    throw new Error('should have thrown')
  } catch (e) {
    if (e.message === 'should have thrown') throw e
    // rejection is correct
  }
})

// AC4: non-date string → rejected
assert('AC4: non-date string is rejected', () => {
  try {
    parseIsoDate('not-a-date')
    throw new Error('should have thrown')
  } catch (e) {
    if (e.message === 'should have thrown') throw e
  }
})

// AC5: non-string → rejected (throws)
assert('AC5: non-string input throws', () => {
  try {
    parseIsoDate(12345)
    throw new Error('should have thrown')
  } catch (e) {
    if (e.message === 'should have thrown') throw e
  }
})

console.log()
console.log(passed + ' passed, ' + failed + ' failed')
process.exit(failed > 0 ? 1 : 0)
"
